 const [zoom,setZoom]=useState<{rows:typeof rows;startIndex?:number;endIndex?:number}|null>(null);
 const selection=useMemo(()=>industryChartSelection(rows,zoom?.rows===rows?zoom:null,{unit:d.unit,mode}),[rows,zoom,d.unit,mode]);
 const changeZoom=useCallback((next:{startIndex?:number;endIndex?:number})=>setZoom(previous=>previous?.rows===rows&&previous.startIndex===next.startIndex&&previous.endIndex===next.endIndex?previous:{rows,...next}),[rows]);
 const {visibleRows}=selection;
