function transmission(d:MetricDefinition){if(d.family==='capex')return '资本投入变化可能带动机房、服务器和芯片采购；结合项目建设、业务结构与收入兑现，判断投入去向。';if(d.category==='costs'||d.family==='electricity')return '价格变化可能改变材料或运营成本，也可能反映供给、天气和需求变化；不同产业环节的影响方向不同。';if(d.category==='cloud')return '云业务收入和利润用于检验前期投入是否兑现；不同公司的业务边界、租赁和订单定义需要分别核对。';return '收入、订单和库存的共同变化可提供产业需求线索，仍需核对交付、毛利率和客户集中度。'}

function CostComparison({data}:{data:IndustryDataset}){const defs=data.definitions.filter(d=>['WB.copper','WB.aluminum','WB.natural_gas','EIA.VA.commercial'].includes(d.id));const maps=defs.map(d=>new Map((data.series[d.id]?.observations??[]).map(p=>[p.periodEnd.slice(0,7),p.value])));const months=[...new Set(maps.flatMap(m=>[...m.keys()]))].sort().filter(date=>maps.every(m=>m.get(date)!=null&&m.get(date)!>0));const chosen=months.slice(-37);const rows=chosen.map(date=>({date,...Object.fromEntries(defs.map((d,i)=>[d.id,maps[i].get(date)!/maps[i].get(chosen[0])!*100]))}));return <IndustryDisclosure panelKey="industry:metric-support:cost-comparison" scope="metric-support" defaultOpen={false} title="上游成本对比 · 共同起点＝100" summary={<p className="industry-small">统一月度频率 · 共同月份 · 比较各指标的相对涨跌幅</p>}><div className="industry-comparison-chart"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={rows}><XAxis dataKey="date" tick={{fontSize:10}} minTickGap={45}/><YAxis tick={{fontSize:10}}/><Tooltip/><ReferenceLine y={100} stroke="#b7c9c1"/>{defs.map((d,i)=><Line key={d.id} dataKey={d.id} name={d.nameZh} stroke={color[i]} dot={false}/>)}</ComposedChart></ResponsiveContainer></div><div className="industry-table-wrap"><table><thead><tr><th>指标</th><th>原始价格</th><th>1个月</th><th>3个月</th><th>12个月/同比</th></tr></thead><tbody>{defs.map(d=>{const obs=data.series[d.id]?.observations??[];const last=obs.at(-1);const change=(months:number)=>{if(!last)return null;const dt=new Date(last.periodEnd);dt.setUTCDate(1);dt.setUTCMonth(dt.getUTCMonth()-months);const p=obs.find(p=>p.periodEnd.slice(0,7)===dt.toISOString().slice(0,7));return p?.value&&last.value!=null?(last.value/p.value-1)*100:null};return <tr key={d.id}><td>{d.nameZh}</td><td>{format(last?.value)} {d.unit}</td><td>{pct(change(1))}</td><td>{pct(change(3))}</td><td>{pct(change(12))}</td></tr>})}</tbody></table></div></IndustryDisclosure>}
const projectStatusLabel:Record<string,string>={announced:'已公告',planning:'规划/谈判',approval:'审批',construction:'在建（公告口径）',partially_operational:'部分投运',operational:'已投运',delayed:'延期',cancelled:'取消',unknown:'未知'};
const projectStateCode=(project:{stateCode?:string;region?:string})=>project.stateCode||({Ohio:'OH','South Carolina':'SC',Idaho:'ID',Indiana:'IN',Louisiana:'LA',Texas:'TX',Virginia:'VA',Georgia:'GA',Arizona:'AZ'}[project.region??'']);
const capacityKindLabel:Record<string,string>={compute_capacity:'计算容量',data_center_planned_capacity:'数据中心规划容量',operational_data_center_capacity:'已投运数据中心容量',grid_interconnection_capacity:'并网容量',onsite_generation_capacity:'现场发电容量',unspecified_project_capacity:'项目披露容量（未细分口径）'};
const capacityDisclosure=(item:{powerCapacityMw?:number;capacityMw?:number;capacityKind?:string})=>{const value=item.powerCapacityMw??item.capacityMw;return typeof value==='number'?value.toLocaleString()+' MW · '+(capacityKindLabel[item.capacityKind??'unspecified_project_capacity']??'项目披露容量（未细分口径）'):'未披露';};
const projectSourceState=(project:{sourceUrls:string[]},data:IndustryDataset)=>{const sources=(data.sources??[]).filter(source=>project.sourceUrls.includes(source.url));if(sources.some(source=>source.status==='ready'))return {state:'ready',label:'本轮已核验'};if(sources.some(source=>source.status==='fetch_failed'))return {state:'cached',label:'来源本轮获取失败，展示历史记录'};return {state:'historical',label:'历史项目记录（本轮未核验）'};};
const eventSourceState=(sourceUrl:string|undefined,data:IndustryDataset)=>{const source=(data.sources??[]).find(item=>item.url===sourceUrl);return source?.status==='ready'?{state:'ready',label:'本轮已核验'}:source?.status==='fetch_failed'?{state:'cached',label:'来源本轮获取失败，展示历史记录'}:{state:'historical',label:'历史事件记录（本轮未核验）'};};
const capacitySummary=(items:{powerCapacityMw?:number;capacityMw?:number;capacityKind?:string}[])=>{const values=items.flatMap(item=>{const value=item.powerCapacityMw??item.capacityMw;return typeof value==='number'?[{value,kind:item.capacityKind??'unspecified_project_capacity'}]:[]});if(!values.length)return {headline:'未披露',detail:'当前样本没有可核验的MW披露。'};const kinds=new Set(values.map(item=>item.kind));if(kinds.size!==1)return {headline:'口径不同',detail:'不同类型的MW按项目展示，不合并为单一总数。'};const kind=[...kinds][0];return {headline:values.reduce((sum,item)=>sum+item.value,0).toLocaleString()+' MW',detail:'同口径样本合计 · '+(capacityKindLabel[kind]??'项目披露容量（未细分口径）')+'。'};};
function ProjectPulse({data,compact=false}:{data:IndustryDataset;compact?:boolean}){
 const events=uniqueProjectEvents(data.projects.flatMap(project=>{const history=project.statusHistory?.length?project.statusHistory:project.announcedAt?[{date:project.announcedAt,status:project.status,sourceUrl:project.sourceUrls[0],capacityMw:project.powerCapacityMw,capacityKind:project.capacityKind,note:'仅有首次公告日期，尚未形成完整生命周期记录。'}]:[];return history.map(event=>({...event,projectId:project.id,projectName:project.name}))}).filter(event=>/^\d{4}-\d{2}-\d{2}$/.test(event.date)));
 const cutoff=new Date();cutoff.setUTCDate(cutoff.getUTCDate()-90);
 const recent=events.filter(event=>Date.parse(event.date+'T00:00:00Z')>=cutoff.getTime()&&eventSourceState(event.sourceUrl,data).state==='ready');
 const currentProjects=data.projects.filter(project=>projectSourceState(project,data).state==='ready');
 const construction=currentProjects.filter(project=>project.status==='construction'&&typeof project.powerCapacityMw==='number');
 const planning=currentProjects.filter(project=>['announced','planning','approval'].includes(project.status)&&typeof project.powerCapacityMw==='number');
 const recentCapacity=capacitySummary(recent);
 const constructionCapacity=capacitySummary(construction);
 const planningCapacity=capacitySummary(planning);
 if(compact)return <section className="industry-panel project-pulse"><h3>建设进度快照</h3><p><strong>{constructionCapacity.headline}</strong> 已核验在建项目样本</p><small>{constructionCapacity.detail} 近90日官方状态更新 {recent.length||'暂无'} 项；样本不代表全量市场。</small></section>;
 return <IndustryDisclosure panelKey="industry:project-lifecycle" title="建设速度与生命周期" className="industry-panel project-pulse" badge={<span className="industry-tag">最近 90 日</span>} summary={<><p>只统计项目级官方公告中的状态更新；不同容量口径按项目保留，未覆盖全量市场时不把“未检出”解释为零。</p><p className="industry-small">当前已核验在建样本：{constructionCapacity.headline} · 最近90日状态更新：{recent.length||'未检出'}</p></>}><div className="project-pulse-grid"><article><span>本轮已核验状态更新</span><strong>{recent.length||'未检出'}</strong><small>{recent.length?recent.map(event=>event.projectName).join('、'):'当前已接入样本没有落入近90日且本轮核验通过的状态事件。'}</small></article><article><span>更新涉及容量</span><strong>{recentCapacity.headline}</strong><small>{recentCapacity.detail} 不代表新增在建或新增投运。</small></article><article><span>当前在建样本</span><strong>{constructionCapacity.headline}</strong><small>{construction.length} 个本轮已核验且披露容量的在建项目。{constructionCapacity.detail}</small></article><article><span>规划/审批样本</span><strong>{planningCapacity.headline}</strong><small>{planning.length} 个本轮已核验且披露容量的项目；不计入在建项目样本。{planningCapacity.detail}</small></article></div>{events.length?<details><summary>项目生命周期事件（{events.length}）</summary><div className="industry-table-wrap"><table><thead><tr><th>日期</th><th>项目</th><th>状态</th><th>披露容量 / 口径</th><th>官方来源 / 新鲜度</th></tr></thead><tbody>{events.map(event=>{const sourceState=eventSourceState(event.sourceUrl,data);return <tr key={event.eventKey}><td>{event.date}</td><td>{event.projectName}<small>{event.note}</small></td><td>{projectStatusLabel[event.status]??event.status}</td><td>{capacityDisclosure(event)}</td><td><a href={event.sourceUrl} target="_blank" rel="noreferrer">公告 ↗</a><small>{sourceState.label}</small></td></tr>})}</tbody></table></div></details>:null}</IndustryDisclosure>
}
const projectMapPositions:Record<string,{x:number;y:number}>={ID:{x:25,y:30},TX:{x:47,y:70},LA:{x:62,y:72},IN:{x:65,y:43},OH:{x:70,y:39},SC:{x:77,y:57},VA:{x:76,y:49},GA:{x:73,y:61},AZ:{x:35,y:58}};
const projectStateNames:Record<string,string>={ID:'爱达荷州',TX:'得克萨斯州',LA:'路易斯安那州',IN:'印第安纳州',OH:'俄亥俄州',SC:'南卡罗来纳州',VA:'弗吉尼亚州',GA:'佐治亚州',AZ:'亚利桑那州'};
const projectStatusTone:Record<string,string>={construction:'construction',planning:'planning',approval:'planning',announced:'announced',partially_operational:'operational',operational:'operational',delayed:'delayed',cancelled:'delayed',unknown:'announced'};
function ProjectRegionMap({data}:{data:IndustryDataset}){
 const [selected,setSelected]=useState<string|null>(null);
 const regions=[...new Map(data.projects.map(project=>[projectStateCode(project),project])).entries()].filter(([code])=>!!code).map(([code,project])=>{const projects=data.projects.filter(item=>projectStateCode(item)===code);const definition=data.definitions.find(item=>item.id===`EIA.${code}.industrial`);const series=definition?data.series[definition.id]:undefined;return {code:code!,projects,definition,series,latest:series?.observations.at(-1),position:projectMapPositions[code!]}}).sort((a,b)=>a.code.localeCompare(b.code));
 if(!regions.length)return null;
 const selectedCode=selected??regions[0].code;
 const active=regions.find(region=>region.code===selectedCode)??regions[0];
 return <IndustryDisclosure panelKey="industry:project-region-map" title="项目区域与电力背景" className="industry-panel project-region-map" badge={<span className="industry-tag"><MapPin size={14}/> 区域示意图</span>} summary={<p>按项目披露的州级地区定位；点击圆点或州卡查看项目状态和 EIA 工业电价背景。</p>}><div className="project-map-layout"><div className="project-map-frame"><svg viewBox="0 0 100 90" role="img" aria-label="美国项目州级区域示意图"><path className="project-map-outline" d="M12 33 L24 25 L38 28 L48 31 L60 28 L73 34 L88 43 L83 58 L76 65 L66 63 L56 76 L42 72 L33 64 L25 56 L17 49 Z"/>{regions.map(region=>region.position?<g key={region.code} className={`project-map-point ${selectedCode===region.code?'selected':''}`} role="button" tabIndex={0} aria-label={`${projectStateNames[region.code]??region.code}，${region.projects.length}个项目`} onClick={()=>setSelected(region.code)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();setSelected(region.code)}}}><circle cx={region.position.x} cy={region.position.y} r="4.5" className={projectStatusTone[region.projects[0].status]}/><text x={region.position.x} y={region.position.y+1}>{region.code}</text></g>:null)}</svg><small>示意位置，不代表园区精确坐标或并网位置。</small></div><div className="project-region-list" aria-label="项目州列表">{regions.map(region=><button key={region.code} className={selectedCode===region.code?'selected':''} onClick={()=>setSelected(region.code)}><span className={`project-region-dot ${projectStatusTone[region.projects[0].status]}`}/><strong>{region.code} · {projectStateNames[region.code]??region.projects[0].region}</strong><small>{region.projects.length} 项 · {projectStatusLabel[region.projects[0].status]}</small></button>)}</div><article className="project-region-detail" aria-live="polite"><span>{active.code} · {projectStateNames[active.code]??active.projects[0].region}</span><h4>{active.projects.map(project=>project.name).join('、')}</h4><p><b>{projectStatusLabel[active.projects[0].status]}</b> · 披露容量 {active.projects.map(project=>project.powerCapacityMw==null?'未披露':`${project.powerCapacityMw.toLocaleString()} MW`).join('、')}</p><dl><div><dt>工业平均电价</dt><dd>{active.latest?.value==null?'未发布':`${format(active.latest.value)} ${active.definition?.unit??''}`}</dd></div><div><dt>观测期</dt><dd>{active.latest?.periodEnd??'尚无观测'}</dd></div><div><dt>数据状态</dt><dd>{statusText(active.series)}</dd></div></dl>{active.definition&&<a href={active.definition.sourceUrl} target="_blank" rel="noreferrer">{active.definition.sourceName} ↗</a>}<small>州级工业平均零售电价只是成本背景，不是数据中心合同价，也不能单独证明并网或供电可得性。</small></article></div></IndustryDisclosure>
}
function ProjectPowerContext({data}:{data:IndustryDataset}){const rows=[...new Map(data.projects.map(project=>[projectStateCode(project),project])).entries()].filter(([code])=>!!code).map(([code,project])=>{const definition=data.definitions.find(item=>item.id===`EIA.${code}.industrial`);const series=definition?data.series[definition.id]:undefined;const latest=series?.observations.at(-1);return {code,project,definition,series,latest}});return <IndustryDisclosure panelKey="industry:project-power" title="项目所在地的电力背景" summary={<p>用 EIA 州级工业平均零售电价观察区域用电成本，再结合项目电力合同与并网进度判断。</p>}><div className="industry-table-wrap"><table><thead><tr><th>州 / 关联项目</th><th>工业平均电价</th><th>观测期</th><th>数据状态</th></tr></thead><tbody>{rows.map(({code,project,definition,series,latest})=><tr key={code}><td>{code} · {project.region}<small>{project.name}</small></td><td>{latest?.value==null?'未发布':`${format(latest.value)} ${definition?.unit??''}`}</td><td>{latest?.periodEnd??'尚无观测'}</td><td>{statusText(series)}{definition&&<small><a href={definition.sourceUrl} target="_blank" rel="noreferrer">{definition.sourceName} ↗</a></small>}</td></tr>)}</tbody></table></div></IndustryDisclosure>}
function PackagingMilestones({data}:{data:IndustryDataset}){
 const events=data.events.filter(event=>event.entity==='ASX'&&event.isConfirmed).sort((a,b)=>b.date.localeCompare(a.date));
 if(!events.length)return null;
 return <IndustryDisclosure panelKey="industry:metric-support:packaging-milestones" scope="metric-support" defaultOpen={false} title="先进封装：官方项目与产线进度" summary={<p className="industry-muted">实际开工与未来投产计划分别标明。项目公告提供直接线索；连续季度产能、单项收入和订单尚未公开齐备，仍不替代正式评分。</p>}><PanelExplorer storageKey="industry:packaging-events" title="选择官方项目事件" items={events.map(event=>({id:event.id,title:event.title,summary:event.observationNature==='forecast'?'未来投产计划':'已确认开工事件',meta:event.date}))} renderPanel={id=>{const event=events.find(item=>item.id===id);return event?<article className="industry-mini-card" key={event.id}><span className="industry-tag">{event.observationNature==='forecast'?'未来投产计划':'已确认开工事件'} · {event.status==='cached'?'展示缓存':'官方披露'}</span><h4>{event.title}</h4><p>{event.description}</p><a href={event.sourceUrl} target="_blank" rel="noreferrer">{event.date} · 查看官方公告 ↗</a><small>获取 {displayTime(event.fetchedAt)} · 版本 {event.version?.slice(0,12)}</small>{event.error&&<small>{event.error}</small>}</article>:null}}/></IndustryDisclosure>
}
function ProjectPanel({data}:{data:IndustryDataset}){
 const progress=['PROJECT.construction_capacity','PROJECT.operational_capacity'].map(id=>({definition:data.definitions.find(d=>d.id===id),series:data.series[id]}));
 return <IndustryDisclosure panelKey="industry:metric-support:projects" scope="metric-support" defaultOpen={false} title="公开数据中心项目登记" summary={<p className="industry-small">按项目查看建设状态、容量与官方公告 · {data.projects.length} 个公开样本</p>}>
 <div className="industry-two-col">{progress.map(({definition,series})=>{const latest=series?.observations?.at(-1);return <article className="industry-mini-card" key={definition?.id}><strong>{definition?.nameZh}</strong><b>{latest?.value==null?'—':latest.value.toLocaleString()+' '+(definition?.unit??'')}</b><small>{statusText(series)} · {series?.note??'等待来源检查'}</small></article>})}</div>
 <PanelExplorer storageKey="industry:project-support" title="项目观察" items={[
 {id:'registry',title:'项目登记',summary:data.projects.length+' 个公开样本'},
 {id:'lifecycle',title:'建设速度与生命周期',summary:'近90日状态更新',panelKey:'industry:project-lifecycle'},
 {id:'regions',title:'区域分布',summary:'项目与州级电力背景',panelKey:'industry:project-region-map'},
 {id:'power',title:'所在地用电成本',summary:'州级工业平均电价',panelKey:'industry:project-power'},
 {id:'sources',title:'来源检查',summary:(data.sources?.length??0)+' 项来源'}
 ]} renderPanel={id=>id==='lifecycle'?<ProjectPulse data={data}/>:id==='regions'?<ProjectRegionMap data={data}/>:id==='power'?<ProjectPowerContext data={data}/>:id==='sources'?<div className="industry-source-status"><strong>来源检查</strong>{data.sources?.length?data.sources.map(source=><p key={source.id}><a href={source.url} target="_blank" rel="noreferrer">{source.name} ↗</a> · {statusLabels[source.status]??source.status}{source.error?' · '+source.error:''}</p>):<p>尚无已配置来源记录。</p>}</div>:data.projects.length?<><p className="industry-small">项目按唯一ID登记；容量类型、状态和来源分别保留。</p><PanelExplorer storageKey="industry:project-records" title="选择项目" items={data.projects.map(project=>({id:project.id,title:project.name,eyebrow:project.owner,summary:projectStatusLabel[project.status],meta:project.country+' · '+project.region}))} renderPanel={projectId=>{const project=data.projects.find(item=>item.id===projectId);return project?<article className="industry-panel"><h3>{project.name}</h3><p>{project.owner} · {project.country} {project.region}</p><div className="industry-source-summary"><span>{projectStatusLabel[project.status]}</span><span>{capacityDisclosure(project)}</span></div><p>{project.notes}</p><p>预计投运 {project.expectedOperationalAt??'未披露'} · 核验 {displayTime(project.lastVerifiedAt)}</p><p>{project.sourceUrls.map(url=><a key={url} href={url} target="_blank" rel="noreferrer">官方来源 ↗ </a>)}</p></article>:null}}/></>:<div className="industry-empty"><Building2 size={29}/><strong>项目数据库待接入</strong><p>尚无通过核验的公开项目样本。</p></div>}/>
 </IndustryDisclosure>
}

function History({history:source}:{history:Recommendation[]}){const history=[...source].sort((a,b)=>b.generatedAt.localeCompare(a.generatedAt)).slice(0,10);return <IndustryDisclosure panelKey="research:recommendation-history" title="建议版本与变化原因" scope="research" summary={<p className="industry-small">从本模块首次运行开始保存；不回填假设性的历史评级。</p>}>{history.length?<div className="industry-table-wrap"><table><thead><tr><th>生成时间</th><th>产业环节</th><th>建议变化</th><th>原因与规则</th></tr></thead><tbody>{history.map(r=><tr key={r.id+'-'+r.generatedAt}><td>{displayTime(r.generatedAt)}</td><td>{r.targetName}</td><td>{r.previousLevel?labelLevel(r.previousLevel)+' → ':''}{labelLevel(r.level)}</td><td>{r.changeReason}<small>{r.ruleVersion} · {r.id}</small></td></tr>)}</tbody></table></div>:<p className="industry-muted">建议历史将在打开本页时按需读取。</p>}</IndustryDisclosure>}
function Sources({data,now}:{data:IndustryDataset;now:string}){const [query,setQuery]=useState(''),[category,setCategory]=useState('all'),[page,setPage]=useState(0);const catalogPage=sourceCatalogPage(data.definitions,{search:query,category,page});const unavailable=data.definitions.filter(def=>!(data.series[def.id]?.observations??[]).some(point=>point.value!=null));const incomplete=data.definitions.map(def=>({def,completeness:historyCompleteness(def,data.series[def.id]?.observations??[])})).filter(item=>item.completeness.missingPeriods.length>0);return <div id="industry-sources"><div className="industry-source-summary"><span><b>{data.definitions.length-unavailable.length}</b> 项已接入</span><span><b>{unavailable.length}</b> 项待接入</span><span><b>{incomplete.length}</b> 项有历史空档</span></div><PanelExplorer storageKey="industry:source-definitions" title="指标目录与计算口径" items={[
{id:'catalog',title:'查指标与来源',summary:data.definitions.length+' 项指标',anchor:'industry-source-catalog',panelKey:'industry:sources:catalog'},
{id:'completeness',title:'数据完整性',summary:incomplete.length+' 项有历史空档',panelKey:'industry:sources:completeness'},
{id:'time',title:'日期、单位与修订',summary:'同比、环比、报告期',panelKey:'industry:sources:time'},
{id:'rules',title:'方向规则',summary:RULE_VERSION,panelKey:'industry:sources:rules'},
{id:'updates',title:'后台怎样更新',summary:'获取、重试、缓存',panelKey:'industry:sources:updates'},
{id:'boundaries',title:'指标适用范围',summary:'公司、产业与地区口径',panelKey:'industry:sources:boundaries'}
]} renderPanel={id=>id==='catalog'?<><IndustryDisclosure panelKey="industry:sources:catalog" title="全部指标与来源状态" summary={<p className="industry-small">指标目录共 {data.definitions.length} 项，保留每项来源、观测期和数据状态。</p>}><div className="industry-catalog-controls"><label>搜索指标或来源<input value={query} onChange={e=>{setQuery(e.target.value);setPage(0)}} placeholder="公司、指标名称、来源机构"/></label><label>产业环节<select value={category} onChange={e=>{setCategory(e.target.value);setPage(0)}}><option value="all">全部环节</option>{categories.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label></div><p className="industry-small">筛选到 {catalogPage.count} 项 · 每页 8 项</p><details className="industry-topic-details"><summary>指标类型说明</summary><div className="industry-type-key">{Object.entries(labels).map(([k,v])=><span className="industry-tag" key={k}>{v}</span>)}</div></details><div className="industry-table-wrap industry-catalog-table"><table><thead><tr><th>指标 / 来源</th><th>类型 / 口径</th><th>频率 / 单位</th><th>最新期 / 获取时间</th><th>状态 / 许可</th></tr></thead><tbody>{catalogPage.items.map(d=>{const s=data.series[d.id],st=metricStats(d,s?.observations??[],now);return <tr key={d.id}><td>{d.entity} · {d.nameZh}<small>{d.id}</small><a href={d.sourceUrl} target="_blank" rel="noreferrer">{d.sourceName} ↗</a></td><td>{labels[d.valueType]}<small>{d.methodology}</small></td><td>{freq[d.frequency]} · {d.unit}<small>{d.currency??'无币种转换'}</small></td><td>{st.latest?.periodEnd??'尚无观测'}<small>{displayTime(s?.fetchedAt)}</small></td><td>{statusText(s)}{st.freshness==='stale'?' · 过期':''}<small>{d.exportAllowed?'事实数值CSV可导出':'导出待核验许可'}</small>{s?.note&&<small>{s.note}</small>}{s?.error&&<small>{s.error}</small>}</td></tr>})}</tbody></table></div>{!catalogPage.count&&<p className="industry-empty">没有符合条件的指标。<button className="industry-text-button" onClick={()=>{setQuery('');setCategory('all');setPage(0)}}>清除筛选</button></p>}<div className="industry-catalog-pagination"><button onClick={()=>setPage(catalogPage.page-1)} disabled={catalogPage.page===0}>上一页</button><span>{catalogPage.page+1} / {catalogPage.pages}</span><button onClick={()=>setPage(catalogPage.page+1)} disabled={catalogPage.page+1>=catalogPage.pages}>下一页</button></div></IndustryDisclosure></>:id==='completeness'?<><IndustryDisclosure panelKey="industry:sources:completeness" title="数据完整性" summary={<p>已接入 {data.definitions.length-unavailable.length} / {data.definitions.length} 个指标；未接入 {unavailable.length} 个。缺失期、来源失败和尚未发布会保留为空，不用零值、插值或上一期数值补齐。</p>}>{incomplete.length?<ul className="industry-quality-list">{incomplete.slice(0,6).map(({def,completeness})=><li key={def.id}><strong>{def.entity} · {def.nameZh}</strong><span>{completeness.observedPeriods}/{completeness.expectedPeriods} 期；缺 {completeness.missingPeriods.map(period=>period.slice(0,7)).join('、')}</span></li>)}</ul>:<p className="industry-small">当前已接入指标的历史期数连续。</p>}{incomplete.length>6&&<p className="industry-small">另有 {incomplete.length-6} 个指标存在历史空档，详见各图的数据完整度。</p>}</IndustryDisclosure></>:id==='time'?<><IndustryDisclosure panelKey="industry:sources:time" title="数据、时间与修订" summary={<p>报告期末、财年季度、来源发布日期与获取时间分别保存。现金流年度累计值只有在基期匹配时才能差分为单季。</p>}><p>同比 = 本期/上年同期 − 1；环比 = 本期/上期 − 1。百分比指标的变化以百分点解释。缺基期或非正基期时不计算变化率。</p><p>从首次获取开始记录新修订。首次历史导入代表当前可得数据，不代表过去当时已知数据。</p></IndustryDisclosure></>:id==='rules'?<><IndustryDisclosure panelKey="industry:sources:rules" title={'建议规则 '+RULE_VERSION} summary={<p>投入、需求、建设、盈利、成本五维分别展示正反证据；同一维度按独立证据组取代表信号，相反信号可以形成中性，不用隐蔽分数相抵。</p>}><p>各产业环节的必需维度必须齐备，并满足该环节规定的需求公司覆盖数，才会生成正式建议。演示、估计、指引、未核验第三方、过期、无基期或获取失败的数据不参与计算。</p><p>投入、订单、收入、盈利中至少三类指标的同比增速连续两个报告期恶化时降低暴露；两类时谨慎观望。必需维度齐备且至少四维正面、无负面维度时积极配置；至少三维正面时分批关注。</p><p>成本上涨对制造端与上游矿业不是同一含义。本版不凭商品涨价推荐矿业配置，也不把产业建议理解为个股买卖信号。</p></IndustryDisclosure></>:id==='updates'?<><IndustryDisclosure panelKey="industry:sources:updates" title="后台更新" summary={<p>GitHub Actions 独立于网页约每15分钟检查调度；财报和月度数据源每日检查，失败保留最后成功数据并重试。调度可能延迟。</p>}><p>MU、ETN、VRT公司整体财务由SEC官方XBRL自动获取；TSMC季度数据从官网业绩文件获取，当前季度结束后21天开始探测，不宣称即时财报。公司财报从官方发布列表自动发现新地址；通过财季、单位和实际数值校验后才进入图表。未知表格格式显示“已发布待采集”，来源失败时保留缓存。CSO季度用电每年集中发布；IEA仅解析固定版本报告的情景值。官方明确公告的下一次发布时间会列出；未提供安排时显示未知。发布列表后台每小时检查，已发布待采集会重试，网页关闭后继续运行。</p><p>数据、建议版本与完整复算档案保存在独立 data-cache 分支。网页刷新只重读后台缓存；Windows采集子进程在后台隐藏运行。</p></IndustryDisclosure></>:<><IndustryDisclosure panelKey="industry:sources:boundaries" title="使用边界" summary={<p>公司总资本开支不是纯AI投入；Intelligent Cloud不等同Azure；Meta广告收入不能与云收入相加；全球半导体统计不等于AI芯片需求。</p>}><p>全国与州级商业/工业平均电价不是数据中心合同价。SIA/WSTS完整历史、HBM现货/合约价、全球项目全量、实时封装产能等需进一步落实授权。</p><p>产业配置建议不等于收益保证；个股功能仍缺行情、估值、一致预期、财务风险和重大事件的完整联合校验。</p></IndustryDisclosure></>}/></div>}
